def split_csv(line):
    fields = []
    i = 0

    while i <= len(line):
        if i == len(line):
            # End of line
            fields.append('')
            break

        if line[i] == '"':
            # Quoted field
            i += 1
            field = ''
            while i < len(line):
                if line[i] == '"':
                    if i + 1 < len(line) and line[i + 1] == '"':
                        # Doubled quote
                        field += '"'
                        i += 2
                    else:
                        # End of quoted field
                        i += 1
                        # Next should be comma or end of line
                        if i < len(line):
                            if line[i] == ',':
                                i += 1
                                fields.append(field)
                                if i == len(line):
                                    fields.append('')
                            else:
                                # Invalid: quote not followed by comma or EOL
                                return None
                        else:
                            # End of line
                            fields.append(field)
                        break
                else:
                    field += line[i]
                    i += 1
            else:
                # Reached end of line without closing quote
                return None
        else:
            # Unquoted field
            field = ''
            while i < len(line) and line[i] != ',':
                if line[i] == '"':
                    # Double quote in unquoted field is invalid
                    return None
                field += line[i]
                i += 1

            fields.append(field)
            if i < len(line):
                # Skip the comma
                i += 1
                if i == len(line):
                    fields.append('')

    return fields

